277:     */
278:    @Override
279:    public final void onCreate(@NonNull LifecycleOwner owner) {
280:        if (getAvailabilityStatus() == UNSUPPORTED_ON_DEVICE) {
281:            mPreference.setVisible(false);
282:            return;
283:        }
284:        onCreateInternal();
285:        mIsCreated = true;
286:        refreshUi();
