398:        while (mActivityResultCallbackMap.indexOfKey(mCurrentRequestIndex) >= 0) {
399:            mCurrentRequestIndex =
400:                    (mCurrentRequestIndex + 1) % MAX_NUM_PENDING_ACTIVITY_RESULT_CALLBACKS;
