68:    public void onCreate(Bundle savedInstanceState) {
69:        super.onCreate(savedInstanceState);
70:
71:        mResetButton = new MenuItem.Builder(getContext())
72:                .setTitle(R.string.reset_app_pref_button_text)
73:                .setOnClickListener(i -> resetAppPreferences())
74:                .build();
