77:    private void resetAppPreferences() {
78:        mResetTask = new ResetTask(requireContext().getApplicationContext());
79:        mResetTask.execute();
80:    }
81:
82:    private static class ResetTask extends AsyncTask<Void, Void, Void> {
83:
84:        private final WeakReference<Context> mContext;
85:
86:        ResetTask(Context context) {
87:            mContext = new WeakReference<>(context);
88:        }
89:
90:        @Override
91:        protected Void doInBackground(Void... unused) {
92:            Context context = mContext.get();
93:            if (context == null) {
94:                LOG.w("Unable to reset app preferences. Null context");
95:                return null;
96:            }
97:            PackageManager packageManager = context.getPackageManager();
98:            IBinder notificationManagerServiceBinder = ServiceManager.getService(
99:                    Context.NOTIFICATION_SERVICE);
100:            if (notificationManagerServiceBinder == null) {
101:                LOG.w("Unable to reset app preferences. Null notification manager service");
102:                return null;
103:            }
104:            INotificationManager notificationManagerService =
105:                    INotificationManager.Stub.asInterface(notificationManagerServiceBinder);
106:
107:            // Reset app notifications.
108:            // Reset disabled apps.
109:            List<ApplicationInfo> apps = packageManager.getInstalledApplications(
110:                    PackageManager.MATCH_DISABLED_COMPONENTS);
111:            for (ApplicationInfo app : apps) {
112:                try {
113:                    notificationManagerService.setNotificationsEnabledForPackage(
114:                            app.packageName,
115:                            app.uid, true);
116:                } catch (RemoteException e) {
117:                    LOG.w("Unable to reset notification preferences for app: " + app.name, e);
118:                }
119:                if (!app.enabled) {
120:                    if (packageManager.getApplicationEnabledSetting(app.packageName)
121:                            == PackageManager.COMPONENT_ENABLED_STATE_DISABLED_USER) {
122:                        packageManager.setApplicationEnabledSetting(app.packageName,
123:                                PackageManager.COMPONENT_ENABLED_STATE_DEFAULT,
124:                                PackageManager.DONT_KILL_APP);
125:                    }
126:                }
127:            }
128:
129:            // Reset default applications for actions.
130:            // Reset background data restrictions for apps.
131:            // Reset permission restrictions.
132:            try {
133:                IBinder packageManagerServiceBinder = ServiceManager.getService("package");
134:                if (packageManagerServiceBinder == null) {
135:                    LOG.w("Unable to reset app preferences. Null package manager service");
136:                    return null;
137:                }
138:                IPackageManager.Stub.asInterface(
139:                        packageManagerServiceBinder).resetApplicationPreferences(
140:                        ActivityManager.getCurrentUser());
141:            } catch (RemoteException e) {
142:                LOG.w("Unable to reset app preferences", e);
143:            }
144:
145:            // Cleanup.
146:            context.getSystemService(AppOpsManager.class).resetAllModes();
147:
148:            return null;
149:        }
