151:        @Override
152:        protected void onPostExecute(Void unused) {
153:            super.onPostExecute(unused);
154:            Context context = mContext.get();
155:            if (context != null) {
156:                Toast.makeText(context, R.string.reset_app_pref_complete_toast,
157:                        Toast.LENGTH_SHORT).show();
158:            }
159:        }
160:    }
