41:/**
42: * The utility class that generate a license html file from xml files.
43: * All the HTML snippets and logic are copied from build/make/tools/generate-notice-files.py.
44: */
45:class LicenseHtmlGeneratorFromXml {
46:    private static final Logger LOG = new Logger(LicenseHtmlGeneratorFromXml.class);
47:
48:    private static final String TAG_ROOT = "licenses";
49:    private static final String TAG_FILE_NAME = "file-name";
50:    private static final String TAG_FILE_CONTENT = "file-content";
51:    private static final String ATTR_CONTENT_ID = "contentId";
52:    private static final String HTML_HEAD_STRING =
53:            "<html><head>\n"
54:                    + "<style type=\"text/css\">\n"
55:                    + "body { padding: 0; font-family: sans-serif; }\n"
56:                    + ".same-license { background-color: #eeeeee;\n"
57:                    + "                border-top: 20px solid white;\n"
58:                    + "                padding: 10px; }\n"
59:                    + ".label { font-weight: bold; }\n"
60:                    + ".file-list { margin-left: 1em; color: blue; }\n"
61:                    + "</style>\n"
62:                    + "</head>"
63:                    + "<body topmargin=\"0\" leftmargin=\"0\" rightmargin=\"0\" bottommargin=\"0\">"
64:                    + "\n"
65:                    + "<div class=\"toc\">\n"
66:                    + "<ul>";
67:
68:    private static final String HTML_MIDDLE_STRING =
69:            "</ul>\n"
70:                    + "</div><!-- table of contents -->\n"
71:                    + "<table cellpadding=\"0\" cellspacing=\"0\" border=\"0\">";
72:
73:    private static final String HTML_REAR_STRING =
74:            "</table></body></html>";
75:
76:    private final List<File> mXmlFiles;
77:
78:    /*
79:     * A map from a file name to a content id (MD5 sum of file content) for its license.
80:     * For example, "/system/priv-app/TeleService/TeleService.apk" maps to
81:     * "9645f39e9db895a4aa6e02cb57294595". Here "9645f39e9db895a4aa6e02cb57294595" is a MD5 sum
82:     * of the content of packages/services/Telephony/MODULE_LICENSE_APACHE2.
83:     */
84:    private final Map<String, String> mFileNameToContentIdMap = new HashMap();
85:
86:    /*
87:     * A map from a content id (MD5 sum of file content) to a license file content.
88:     * For example, "9645f39e9db895a4aa6e02cb57294595" maps to the content string of
89:     * packages/services/Telephony/MODULE_LICENSE_APACHE2. Here "9645f39e9db895a4aa6e02cb57294595"
90:     * is a MD5 sum of the file content.
91:     */
92:    private final Map<String, String> mContentIdToFileContentMap = new HashMap();
93:
94:    static class ContentIdAndFileNames {
95:        final String mContentId;
96:        final List<String> mFileNameList = new ArrayList();
97:
98:        ContentIdAndFileNames(String contentId) {
99:            mContentId = contentId;
100:        }
101:    }
102:
103:    private LicenseHtmlGeneratorFromXml(List<File> xmlFiles) {
104:        mXmlFiles = xmlFiles;
105:    }
106:
107:    public static boolean generateHtml(List<File> xmlFiles, File outputFile) {
108:        LicenseHtmlGeneratorFromXml genertor = new LicenseHtmlGeneratorFromXml(xmlFiles);
109:        return genertor.generateHtml(outputFile);
110:    }
111:
112:    private boolean generateHtml(File outputFile) {
113:        for (File xmlFile : mXmlFiles) {
114:            parse(xmlFile);
115:        }
116:
117:        if (mFileNameToContentIdMap.isEmpty() || mContentIdToFileContentMap.isEmpty()) {
118:            return false;
119:        }
120:
121:        PrintWriter writer = null;
122:        try {
123:            writer = new PrintWriter(outputFile);
124:
125:            generateHtml(mFileNameToContentIdMap, mContentIdToFileContentMap, writer);
126:
127:            writer.flush();
128:            writer.close();
129:            return true;
130:        } catch (FileNotFoundException | SecurityException e) {
131:            LOG.e("Failed to generate " + outputFile, e);
132:
133:            if (writer != null) {
134:                writer.close();
135:            }
136:            return false;
137:        }
138:    }
139:
140:    private void parse(File xmlFile) {
141:        if (xmlFile == null || !xmlFile.exists() || xmlFile.length() == 0) {
142:            return;
143:        }
144:
145:        InputStreamReader in = null;
146:        try {
147:            if (xmlFile.getName().endsWith(".gz")) {
148:                in = new InputStreamReader(new GZIPInputStream(new FileInputStream(xmlFile)));
149:            } else {
150:                in = new FileReader(xmlFile);
151:            }
152:
153:            parse(in, mFileNameToContentIdMap, mContentIdToFileContentMap);
154:
155:            in.close();
156:        } catch (XmlPullParserException | IOException e) {
157:            LOG.e("Failed to parse " + xmlFile, e);
158:            if (in != null) {
159:                try {
160:                    in.close();
161:                } catch (IOException ie) {
162:                    LOG.w("Failed to close " + xmlFile);
163:                }
164:            }
165:        }
166:    }
167:
168:    /*
169:     * Parses an input stream and fills a map from a file name to a content id for its license
170:     * and a map from a content id to a license file content.
171:     *
172:     * Following xml format is expected from the input stream.
173:     *
174:     *     <licenses>
175:     *     <file-name contentId="content_id_of_license1">file1</file-name>
176:     *     <file-name contentId="content_id_of_license2">file2</file-name>
177:     *     ...
178:     *     <file-content contentId="content_id_of_license1">license1 file contents</file-content>
179:     *     <file-content contentId="content_id_of_license2">license2 file contents</file-content>
180:     *     ...
181:     *     </licenses>
182:     */
183:    private static void parse(InputStreamReader in, Map<String, String> outFileNameToContentIdMap,
184:            Map<String, String> outContentIdToFileContentMap)
185:            throws XmlPullParserException, IOException {
186:        Map<String, String> fileNameToContentIdMap = new HashMap<String, String>();
187:        Map<String, String> contentIdToFileContentMap = new HashMap<String, String>();
188:
189:        XmlPullParser parser = Xml.newPullParser();
190:        parser.setInput(in);
191:        parser.nextTag();
192:
193:        parser.require(XmlPullParser.START_TAG, "", TAG_ROOT);
194:
195:        int state = parser.getEventType();
196:        while (state != XmlPullParser.END_DOCUMENT) {
197:            if (state == XmlPullParser.START_TAG) {
198:                if (TAG_FILE_NAME.equals(parser.getName())) {
199:                    String contentId = parser.getAttributeValue("", ATTR_CONTENT_ID);
200:                    if (!TextUtils.isEmpty(contentId)) {
201:                        String fileName = readText(parser).trim();
202:                        if (!TextUtils.isEmpty(fileName)) {
203:                            fileNameToContentIdMap.put(fileName, contentId);
204:                        }
205:                    }
206:                } else if (TAG_FILE_CONTENT.equals(parser.getName())) {
207:                    String contentId = parser.getAttributeValue("", ATTR_CONTENT_ID);
208:                    if (!TextUtils.isEmpty(contentId)
209:                            && !outContentIdToFileContentMap.containsKey(contentId)
210:                            && !contentIdToFileContentMap.containsKey(contentId)) {
211:                        String fileContent = readText(parser);
212:                        if (!TextUtils.isEmpty(fileContent)) {
213:                            contentIdToFileContentMap.put(contentId, fileContent);
214:                        }
215:                    }
216:                }
217:            }
218:
219:            state = parser.next();
220:        }
221:        outFileNameToContentIdMap.putAll(fileNameToContentIdMap);
222:        outContentIdToFileContentMap.putAll(contentIdToFileContentMap);
223:    }
224:
225:    private static String readText(XmlPullParser parser)
226:            throws IOException, XmlPullParserException {
227:        StringBuffer result = new StringBuffer();
228:        int state = parser.next();
229:        while (state == XmlPullParser.TEXT) {
230:            result.append(parser.getText());
231:            state = parser.next();
232:        }
233:        return result.toString();
234:    }
235:
236:    private static void generateHtml(Map<String, String> fileNameToContentIdMap,
237:            Map<String, String> contentIdToFileContentMap, PrintWriter writer) {
238:        List<String> fileNameList = new ArrayList();
239:        fileNameList.addAll(fileNameToContentIdMap.keySet());
240:        Collections.sort(fileNameList);
241:
242:        writer.println(HTML_HEAD_STRING);
243:
244:        int count = 0;
245:        Map<String, Integer> contentIdToOrderMap = new HashMap();
246:        List<ContentIdAndFileNames> contentIdAndFileNamesList = new ArrayList();
247:
248:        // Prints all the file list with a link to its license file content.
249:        for (String fileName : fileNameList) {
250:            String contentId = fileNameToContentIdMap.get(fileName);
251:            // Assigns an id to a newly referred license file content.
252:            if (!contentIdToOrderMap.containsKey(contentId)) {
253:                contentIdToOrderMap.put(contentId, count);
254:
255:                // An index in contentIdAndFileNamesList is the order of each element.
256:                contentIdAndFileNamesList.add(new ContentIdAndFileNames(contentId));
257:                count++;
258:            }
259:
260:            int id = contentIdToOrderMap.get(contentId);
261:            contentIdAndFileNamesList.get(id).mFileNameList.add(fileName);
262:            writer.format("<li><a href=\"#id%d\">%s</a></li>\n", id, fileName);
263:        }
264:
265:        writer.println(HTML_MIDDLE_STRING);
266:
267:        count = 0;
268:        // Prints all contents of the license files in order of id.
269:        for (ContentIdAndFileNames contentIdAndFileNames : contentIdAndFileNamesList) {
270:            writer.format("<tr id=\"id%d\"><td class=\"same-license\">\n", count);
271:            writer.println("<div class=\"label\">Notices for file(s):</div>");
272:            writer.println("<div class=\"file-list\">");
273:            for (String fileName : contentIdAndFileNames.mFileNameList) {
274:                writer.format("%s <br/>\n", fileName);
275:            }
276:            writer.println("</div><!-- file-list -->");
277:            writer.println("<pre class=\"license-text\">");
278:            writer.println(contentIdToFileContentMap.get(
279:                    contentIdAndFileNames.mContentId));
280:            writer.println("</pre><!-- license-text -->");
281:            writer.println("</td></tr><!-- same-license -->");
282:
283:            count++;
284:        }
285:
286:        writer.println(HTML_REAR_STRING);
287:    }
288:}

