40:/**
41: * Bridges {@link AppOpsManager} app operation permission information into {@link
42: * AppEntry#extraInfo} as {@link PermissionState} objects.
43: */
44:public class AppStateAppOpsBridge implements AppEntryListManager.ExtraInfoBridge {
45:
46:    private static final Logger LOG = new Logger(AppStateAppOpsBridge.class);
47:
48:    private final Context mContext;
49:    private final IPackageManager mIPackageManager;
50:    private final List<UserHandle> mProfiles;
51:    private final AppOpsManager mAppOpsManager;
52:    private final int mAppOpsOpCode;
53:    private final String mPermission;
54:
55:    /**
56:     * Constructor.
57:     *
58:     * @param appOpsOpCode the {@link AppOpsManager} op code constant to fetch information for.
59:     * @param permission   the {@link android.Manifest.permission} required to perform the
60:     *                     operation.
61:     */
62:    public AppStateAppOpsBridge(Context context, int appOpsOpCode, String permission) {
63:        this(context, appOpsOpCode, permission, AppGlobals.getPackageManager(),
64:                UserManager.get(context).getUserProfiles(),
65:                context.getSystemService(AppOpsManager.class));
66:    }
67:
68:    @VisibleForTesting
69:    AppStateAppOpsBridge(Context context, int appOpsOpCode, String permission,
70:            IPackageManager packageManager, List<UserHandle> profiles,
71:            AppOpsManager appOpsManager) {
72:        mContext = context;
73:        mIPackageManager = packageManager;
74:        mProfiles = profiles;
75:        mAppOpsManager = appOpsManager;
76:        mAppOpsOpCode = appOpsOpCode;
77:        mPermission = permission;
78:    }
79:
80:    @Override
81:    public void loadExtraInfo(List<AppEntry> entries) {
82:        SparseArray<Map<String, PermissionState>> packageToStatesMapByProfileId =
83:                getPackageToStateMapsByProfileId();
84:        loadAppOpModes(packageToStatesMapByProfileId);
85:
86:        for (AppEntry entry : entries) {
87:            Map<String, PermissionState> packageStatesMap = packageToStatesMapByProfileId.get(
88:                    UserHandle.getUserId(entry.info.uid));
89:            entry.extraInfo = (packageStatesMap != null) ? packageStatesMap.get(
90:                    entry.info.packageName) : null;
91:        }
92:    }
93:
94:    private SparseArray<Map<String, PermissionState>> getPackageToStateMapsByProfileId() {
95:        SparseArray<Map<String, PermissionState>> entries = new SparseArray<>();
96:        try {
97:            for (UserHandle profile : mProfiles) {
98:                int profileId = profile.getIdentifier();
99:                List<PackageInfo> packageInfos = getPackageInfos(profileId);
100:                Map<String, PermissionState> entriesForProfile = new ArrayMap<>();
101:                entries.put(profileId, entriesForProfile);
102:                for (PackageInfo packageInfo : packageInfos) {
103:                    boolean isAvailable = mIPackageManager.isPackageAvailable(
104:                            packageInfo.packageName,
105:                            profileId);
106:                    if (shouldIgnorePackage(packageInfo) || !isAvailable) {
107:                        LOG.d("Ignoring " + packageInfo.packageName + " isAvailable="
108:                                + isAvailable);
109:                        continue;
110:                    }
111:                    PermissionState newEntry = new PermissionState();
112:                    newEntry.mRequestedPermissions = packageInfo.requestedPermissions;
113:                    entriesForProfile.put(packageInfo.packageName, newEntry);
114:                }
115:            }
116:        } catch (RemoteException e) {
117:            LOG.w("PackageManager is dead. Can't get list of packages requesting "
118:                    + mPermission, e);
119:        }
120:        return entries;
121:    }
122:
123:    @SuppressWarnings("unchecked") // safe by specification.
124:    private List<PackageInfo> getPackageInfos(int profileId) throws RemoteException {
125:        return mIPackageManager.getPackagesHoldingPermissions(new String[]{mPermission},
126:                PackageManager.GET_PERMISSIONS, profileId).getList();
127:    }
128:
129:    private boolean shouldIgnorePackage(PackageInfo packageInfo) {
130:        return packageInfo.packageName.equals("android")
131:                || packageInfo.packageName.equals(mContext.getPackageName())
132:                || !ArrayUtils.contains(packageInfo.requestedPermissions, mPermission);
133:    }
134:
135:    /** Sets the {@link PermissionState#mAppOpMode} field. */
136:    private void loadAppOpModes(
137:            SparseArray<Map<String, PermissionState>> packageToStateMapsByProfileId) {
138:        // Find out which packages have been granted permission from AppOps.
139:        List<AppOpsManager.PackageOps> packageOps = mAppOpsManager.getPackagesForOps(
140:                new int[]{mAppOpsOpCode});
141:        if (packageOps == null) {
142:            return;
143:        }
144:        for (AppOpsManager.PackageOps packageOp : packageOps) {
145:            int userId = UserHandle.getUserId(packageOp.getUid());
146:            Map<String, PermissionState> packageStateMap = packageToStateMapsByProfileId.get(
147:                    userId);
148:            if (packageStateMap == null) {
149:                // Profile is not for the current user.
150:                continue;
151:            }
152:            PermissionState permissionState = packageStateMap.get(packageOp.getPackageName());
153:            if (permissionState == null) {
154:                LOG.w("AppOp permission exists for package " + packageOp.getPackageName()
155:                        + " of user " + userId + " but package doesn't exist or did not request "
156:                        + mPermission + " access");
157:                continue;
158:            }
159:            if (packageOp.getOps().size() < 1) {
160:                LOG.w("No AppOps permission exists for package " + packageOp.getPackageName());
161:                continue;
162:            }
163:            permissionState.mAppOpMode = packageOp.getOps().get(0).getMode();
164:        }
165:    }
