52:        sb.append(System.lineSeparator());
53:        if (hasFeature(PackageManager.FEATURE_WIFI)) {
54:            addBulletedValue(sb, R.string.reset_network_item_wifi);
55:        }
56:        if (hasFeature(PackageManager.FEATURE_TELEPHONY)) {
